@js:
/**
填写账号密码调试后获取 login_token 和 account，分别填入。
**/
login_name=""
passwd=""
login_token="72d189d2a0d156da93ce5ab66b113cb1"
account="书客511347149127"

var javaImport = new JavaImporter();
javaImport.importPackage(
    Packages.java.lang,
    Packages.javax.crypto.spec,
    Packages.javax.crypto,
    Packages.android.util
);

with(javaImport) {

    function decode(str) {
        let key = SecretKeySpec(java.base64DecodeToByteArray("lXsAUe1NZEw6tAxM9w1Tpq2tU4la2+PwM8evj2C+yB0="), "AES");
        let iv = IvParameterSpec(java.base64DecodeToByteArray("AAAAAAAAAAAAAAAAAAAAAA=="));
        let bytes = Base64.decode(String(str).getBytes(), 2);
        let chipher = Cipher.getInstance("AES/CBC/PKCS7Padding");
        chipher.init(2, key, iv);
        return String(chipher.doFinal(bytes));
    }

}

if (login_name && passwd && !login_token && !account) {
    body = "login_name=" + login_name + "&passwd=" + passwd + "&device_token=ciweimao_&app_version=2.7.039"
    option = {
        "method": "POST",
        "body": String(body)
    }
    url = 'https://app.hbooker.com/signup/login,' + JSON.stringify(option)
    resp = JSON.parse(decode(java.ajax(url)))
    if (resp.code == "100000") {
        java.log('❗️ 这是你的 login_token，请复制 ❗️：' + resp.data.login_token)
        java.log('❗️ 这是你的 account，请复制 ❗️：' + resp.data.reader_info.account)
    } else {
        java.log('❗️ ' + resp.tip + ' ❗️')
    }
} else {
    java.log('❗️ 请登录获取 login_token 和 account ❗️')
}
java.put('login_token',login_token)
java.put('account',account)
body = "count=10&login_token="+login_token+"&key={{key}}&account="+account+"&device_token=ciweimao_&page={{page-1}}"
option = {"method": "POST","body":String(body)}
'https://app.hbooker.com/bookcity/get_filter_search_book_list,' + JSON.stringify(option)

